#!/usr/bin/env python3
"""Repeat the complete German import and compare every generated byte.

Run with Unity closed and with the exporter's Python dependencies available.
This also checks that original vehicle icons survive the regeneration.
"""
from __future__ import annotations
import hashlib
import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / 'Assets/Blitz/Resources/Data'
RESOURCES = DATA.parent


def generated_files():
    files = set(DATA.glob('blitz_germany_1120_*.json'))
    for name in ('tanks', 'tank_models_source_manifest', 'atlas_regions',
                 'hangar_source_manifest', 'small_tank_icons_manifest',
                 'legacy1120_crash_manifest'):
        files.add(DATA / (name + '.json'))
    records = json.loads((DATA / 'blitz_germany_1120_inventory.json').read_text())['records']
    for record in records:
        rid = ''.join(c.upper() for c in record['name'] if c.isalnum())
        folder = RESOURCES / 'Models/Tanks' / rid
        files.update(p for p in folder.rglob('*') if p.is_file())
        if folder.with_suffix('.meta').exists():
            files.add(folder.with_suffix('.meta'))
        for suffix in ('_nodes', '_armor'):
            files.add(DATA / (rid.lower() + suffix + '.json'))
    for name in ('TankIcons', 'SmallTankIcons'):
        folder = RESOURCES / 'Textures' / name
        files.update(folder.glob('*.png'))
        files.update(folder.glob('*.png.meta'))
    return files


def snapshot():
    return {str(p.relative_to(ROOT)): hashlib.sha256(p.read_bytes()).hexdigest()
            for p in sorted(generated_files())}


def main():
    if subprocess.run(['pgrep', '-x', 'Unity'], stdout=subprocess.DEVNULL).returncode == 0:
        raise SystemExit('Stop this verification until Unity has finished; do not export into a live importer.')
    before = snapshot()
    cache = ROOT / '.ci-cache/germany1120-repeat-before.json'
    cache.parent.mkdir(parents=True, exist_ok=True)
    cache.write_text(json.dumps(before, indent=2) + '\n')
    for args in (
        ['Tools/port_blitz_germany_1120.py', '--prepare', '--models', '--rebuild', '--icons', '--crash', '--merge'],
        ['Tools/port_blitz_small_tank_icons.py'],
        ['Tools/port_blitz_480_data.py', '--check'],
    ):
        subprocess.run([sys.executable, *args], cwd=ROOT, check=True)
    after = snapshot()
    changed = [p for p in sorted(set(before) | set(after)) if before.get(p) != after.get(p)]
    result = {'files': len(after), 'changed': changed,
              'full_model_rebuild': True, 'includes_import_metadata': True}
    report = ROOT / 'Logs/germany1120-determinism-full.json'
    report.parent.mkdir(parents=True, exist_ok=True)
    report.write_text(json.dumps(result, indent=2) + '\n')
    print(json.dumps({'files': len(after), 'changed_count': len(changed), 'changed': changed[:20]}))
    raise SystemExit(1 if changed else 0)


if __name__ == '__main__':
    main()
